const MAPBOX_TOKEN = 'YOUR_MAPBOX_PUBLIC_TOKEN';

const resp = $input.first().json;
const text = (resp.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
const clean = text.replace(/```json|```/g, '').trim();

let script;
try {
  script = JSON.parse(clean);
} catch (e) {
  throw new Error('Claude did not return valid JSON. Raw output: ' + clean.slice(0, 500));
}

if (!script.scenes || script.scenes.length !== 4) {
  throw new Error('Expected exactly 4 scenes, got ' + (script.scenes ? script.scenes.length : 0));
}

// Mapbox Static Images: request dims must be <= 1280 each; @2x doubles output.
// 720x1280@2x -> 1440x2560px, plenty for a 1080x1920 canvas with zoom animation.
for (const s of script.scenes) {
  const m = s.map;
  const style = m.style || 'satellite-streets-v12';
  s.image_url = `https://api.mapbox.com/styles/v1/mapbox/${style}/static/${m.lng},${m.lat},${m.zoom},0,45/720x1280@2x?access_token=${MAPBOX_TOKEN}`;
}

const topic = $('Supabase: Next Topic').first().json;

return [{
  json: {
    topic_id: topic.id,
    topic: topic.topic,
    hook: script.hook,
    script: script.script,
    caption: script.caption,
    scenes: script.scenes,
    audio_filename: `audio/reel_${topic.id}_${Date.now()}.mp3`
  }
}];

