={{ (() => {
  const d = $('Parse Script + Build Map URLs').item.json;
  const audioUrl = 'https://YOUR_PROJECT_REF.supabase.co/storage/v1/object/public/reels-assets/' + d.audio_filename;
  const mods = { 'Voiceover.source': audioUrl };
  d.scenes.forEach((s, i) => {
    mods[`Scene${i+1}-Map.source`] = s.image_url;
    mods[`Scene${i+1}-Text.text`] = s.overlay_text;
    mods[`Scene${i+1}-Caption.transcript_source`] = s.voiceover;
  });
  return JSON.stringify({ template_id: 'YOUR_CREATOMATE_TEMPLATE_ID', modifications: mods });
})() }}

